41	LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
42	                                std::string& err) {
43	  err.clear();
44	  LegTriggerArgs out;
45	  if (t.kind == "csr") return out;  // markers detected by plugin/vsim, not argv
46	
47	  const bool fast = role == "fast-leg";
48	  const bool accurate = role == "accurate-leg";
49	  if (!fast && !accurate) return out;  // other roles carry no trigger args
50	
51	  // Required-param lookup. A missing key is a caller bug; surface it (don't
52	  // throw) so plan_argvs can report which step failed.
53	  auto param = [&](const char* key) -> const std::string* {
54	    auto it = t.params.find(key);
55	    if (it == t.params.end()) {
56	      err = "trigger '" + t.kind + "' missing param '" + key + "'";
57	      return nullptr;
58	    }
59	    return &it->second;
60	  };
61	
62	  if (t.kind == "pc") {
63	    if (fast) {
64	      if (const std::string* p = param("enter_pc"))
65	        out.plugin_suffix = ",enter_pc=" + *p;
66	    } else if (const std::string* p = param("exit_pc")) {
67	      out.extra = {"--hybrid-exit-pc", *p};
68	    }
69	    return out;
70	  }
71	  if (t.kind == "icount") {
72	    if (fast) {
73	      if (const std::string* p = param("qemu_icount"))
74	        out.plugin_suffix = ",icount=" + *p;
75	    } else if (const std::string* p = param("vsim_icount")) {
76	      out.extra = {"--hybrid-icount", *p};
77	    }
78	    return out;
79	  }
80	
81	  err = "unknown trigger kind '" + t.kind + "'";
82	  return out;
83	}
